from fractions import Fraction as Q
from math import factorial,comb
from functools import lru_cache

def moment(p,n,a):
 return Q(0) if n%p else Q(factorial(n),factorial(n//p))*a**(n//p)
def falling(n,k):return 0 if n<k else factorial(n)//factorial(n-k)
@lru_cache(None)
def bell(p,a,d,r):
 if r==0:return {0:Q(1)}
 out={}
 for k in range(min(p,r)):
  c=p*a*d*comb(p-1,k)*falling(r-1,k)
  for j,b in bell(p,a,d,r-1-k).items():
   out[j+p-1-k]=out.get(j+p-1-k,Q(0))+c*b
 return {j:b for j,b in out.items() if b}
@lru_cache(None)
def bound(p,T,r):
 return Q(1) if r==0 else p*T*sum(comb(p-1,k)*falling(r-1,k)*bound(p,T,r-1-k) for k in range(min(p,r)))
checks=0;bounds=0;channels=[]
for m in range(1,5):
 p=2*m
 for T in [Q(1),Q(1,2),Q(2),Q(5,7)]:
  a=(-1)**(m+1)*T
  for r in range(13):
   for g in range(17):
    ans=Q(0)
    for k in range(min(p,r+1)):
     j=p-1-k
     if g<j:continue
     ans+=p*a*comb(p-1,k)*falling(r,k)*falling(g,j)*moment(p,r-k+g-j,a)
    assert ans==moment(p,r+1+g,a)
    checks+=1
  for r in range(1,21):
   for scale in range(5):
    d=Q(1,2**scale);R=bell(p,a,d,r);C=bound(p,T,r)
    assert sum(abs(c) for c in R.values())<=C*d
    if r>p:assert sum(abs(c) for c in R.values())<=C*d*d
    if r<=p:
     leading=p*a*falling(p-1,r-1)*d
     j=p-r
     assert R.get(j,Q(0))==leading
     assert sum(abs(c) for i,c in R.items() if i!=j)<=C*d*d
    assert sum(abs(c) for c in bell(p,a,Q(1),r).values())==C
    bounds+=1
  if T==1:
   channels.append(dict(p=p,normalized_channel_coefficients=[str(p*a*falling(p-1,k)) for k in range(p)],drift=str((-1)**(m+1)*factorial(p)*T)))
